// One-time local setup: writes server/.env with freshly generated secrets.
//
// .env is gitignored and never leaves this machine (A.8.9: zero secrets in the
// repo). Production secrets come from Azure Key Vault / DPAPI-protected config
// per plan section 2 and are never generated by this script.
import { randomBytes } from 'node:crypto';
import { existsSync } from 'node:fs';
import { writeFile } from 'node:fs/promises';
import path from 'node:path';

const ENV_PATH = path.resolve(import.meta.dirname, '../../.env');

if (existsSync(ENV_PATH)) {
  console.log('server/.env already exists — leaving it untouched.');
  console.log('Delete it first if you want fresh secrets.');
  process.exit(0);
}

const secret = () => randomBytes(32).toString('hex');

const contents = `# LOCAL DEVELOPMENT ONLY - generated by "npm run dev:setup".
# Gitignored. Never commit. Production secrets come from the vault (plan section 2).

NODE_ENV=development
PORT=3001
APP_BASE_URL=http://localhost:3001

# Local development database started by "npm run dev:db"
DATABASE_URL=postgres://massy_dev:massy_dev@localhost:5433/massy_purchasing

SESSION_SECRET=${secret()}
BREAK_GLASS_KEY=${secret()}

# Synthetic sign-in for development. Config validation REFUSES this when
# NODE_ENV=production - production authenticates via Entra ID only.
AUTH_MODE=dev

# Required only when AUTH_MODE=entra (from the Entra app registration)
ENTRA_TENANT_ID=
ENTRA_CLIENT_ID=
ENTRA_CLIENT_SECRET=
OIDC_REDIRECT_URI=https://purchasing.massymotors.local/api/auth/callback

WEB_DIST_DIR=
TRUST_PROXY=false
DB_SSL_CA_FILE=
LOG_LEVEL=info
`;

await writeFile(ENV_PATH, contents, 'utf8');
console.log(`wrote ${ENV_PATH} with freshly generated development secrets.

Next:
  npm run dev:db     (leave running in its own terminal)
  npm run migrate
  npm run seed
  npm run dev
`);
